#!/usr/bin/env python3
"""Generate the embedded fallback test font (tests/fixtures/fonts/fallback_test_font.h).

A third tiny original font (no third-party font data) used purely to exercise
the fallback-measurement path in font_cache: it maps a single codepoint, 'B',
that the primary glyph-outline test fonts (tests/fixtures/fonts/glyph_test_fonts.h) do NOT
carry. A face that lacks 'B' can then consult this one as its fallback, and
font_cache_get_text_size must measure the fallback advance rather than zero.

Same metrics as the glyph-outline test fonts (1000 units/em, ascent 800,
descent -200, advance 800) so the maths line up.

Regenerate with:  python3 tests/fixtures/fonts/gen_fallback_test_font.py   (needs fontTools)
"""

from pathlib import Path

from fontTools.fontBuilder import FontBuilder
from fontTools.pens.ttGlyphPen import TTGlyphPen

UPEM = 1000
ASCENT = 800
DESCENT = -200
ADVANCE = 800

SQUARE = [(100, 0), (700, 0), (700, 700), (100, 700)]


def square_path(pen):
    pen.moveTo(SQUARE[0])
    for pt in SQUARE[1:]:
        pen.lineTo(pt)
    pen.closePath()


def build_fallback_ttf():
    fb = FontBuilder(UPEM, isTTF=True)
    fb.setupGlyphOrder([".notdef", "B"])
    fb.setupCharacterMap({ord("B"): "B"})
    fb.setupHorizontalMetrics({".notdef": (500, 0), "B": (ADVANCE, 100)})
    fb.setupHorizontalHeader(ascent=ASCENT, descent=DESCENT)
    fb.setupNameTable({"familyName": "EmUiFallbackTest", "styleName": "Regular"})
    fb.setupOS2(sTypoAscender=ASCENT, sTypoDescender=DESCENT)
    fb.setupPost()

    pen = TTGlyphPen(None)
    square_path(pen)
    fb.setupGlyf({".notdef": TTGlyphPen(None).glyph(), "B": pen.glyph()})
    return fb


def font_bytes(fb):
    from io import BytesIO

    buf = BytesIO()
    fb.save(buf)
    return buf.getvalue()


def c_array(name, data):
    lines = [f"static const unsigned char {name}[] = {{"]
    for i in range(0, len(data), 16):
        lines.append("    " + " ".join(f"0x{b:02x}," for b in data[i : i + 16]))
    lines.append("};")
    lines.append(f"static const long {name}_size = {len(data)};")
    return "\n".join(lines)


def main():
    ttf = font_bytes(build_fallback_ttf())
    out = Path(__file__).resolve().parent / "fallback_test_font.h"
    header = "\n".join(
        [
            "#pragma once",
            "",
            "// Embedded fallback test font. GENERATED by tests/fixtures/fonts/gen_fallback_test_font.py -- do not edit;",
            "// regenerate with `python3 tests/fixtures/fonts/gen_fallback_test_font.py` (needs fontTools).",
            "//",
            "// One tiny original TrueType font (1000 units/em, ascent 800, descent -200) mapping a single",
            "// codepoint 'B' (a solid 600x700 square at (100,0), advance 800). 'B' is absent from the",
            "// glyph-outline test fonts (tests/fixtures/fonts/glyph_test_fonts.h), so a primary face built from those can use",
            "// this as its fallback to exercise font_cache's fallback measurement path.",
            "",
            c_array("k_fallback_test_ttf", ttf),
            "",
        ]
    )
    out.write_text(header)
    print(f"wrote {out} ({len(ttf)} TTF bytes)")


if __name__ == "__main__":
    main()
